"use client";

/**
 * BandSummaryCard — expandable panel for one novel's band summary
 * (Spec 2 — Series Generation Context, Task 8).
 *
 * Shows the auto-generated ``full_summary`` (or the user ``override`` when
 * active) plus the ``generated_at`` timestamp. Controls:
 *
 * - Regenerate → POST (``useGenerateBandSummary``).
 * - Override textarea + Save → PATCH (``useUpdateBandSummaryOverride``).
 * - Clear Override → DELETE (``useClearBandSummaryOverride``), only when an
 *   override is active.
 *
 * RULE-04: the override editor lives in its own module
 * (``BandOverrideEditor``). All copy via ``useTranslations("studio")`` under
 * ``series.bandSummary.*`` (none hardcoded).
 */
import { ChevronDown, Loader2, RefreshCw } from "lucide-react";
import { useTranslations } from "next-intl";
import { useState } from "react";
import { BandOverrideEditor } from "@/components/series/BandOverrideEditor";
import { useBandSummary, useGenerateBandSummary } from "@/lib/hooks/useBandSummary";

interface BandSummaryCardProps {
  readonly seriesId: string;
  readonly novelId: string;
}

export function BandSummaryCard({ seriesId, novelId }: BandSummaryCardProps) {
  const t = useTranslations("studio");
  const { data, isLoading } = useBandSummary(seriesId, novelId);
  const generate = useGenerateBandSummary(seriesId, novelId);
  const [open, setOpen] = useState(true);

  if (isLoading) {
    return (
      <div
        data-testid="band-summary-loading"
        className="flex items-center gap-2 py-2 text-xs text-muted-foreground"
      >
        <Loader2 className="h-3 w-3 animate-spin" />
        {t("series.bandSummary.loading")}
      </div>
    );
  }

  // No summary yet (GET 404 → isError, or lazy not triggered). Offer a CTA.
  if (!data) {
    return (
      <div data-testid="band-summary-empty" className="py-1">
        <button
          type="button"
          data-testid="band-summary-generate-cta"
          onClick={() => generate.mutate()}
          disabled={generate.isPending}
          className="flex items-center gap-1 text-xs text-primary hover:underline disabled:opacity-50"
        >
          {generate.isPending ? (
            <Loader2 className="h-3 w-3 animate-spin" />
          ) : (
            <RefreshCw className="h-3 w-3" />
          )}
          {t("series.bandSummary.empty")}
        </button>
      </div>
    );
  }

  const hasOverride = data.override !== null && data.override.trim() !== "";
  const generatedDate = new Date(data.generated_at).toLocaleDateString();

  return (
    <div data-testid="band-summary-card" className="rounded-md border border-border bg-card">
      <button
        type="button"
        data-testid="band-summary-toggle"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        className="flex w-full items-center justify-between gap-2 px-3 py-2 text-left"
      >
        <span className="flex items-center gap-2 text-xs font-medium text-foreground">
          {t("series.bandSummary.title")}
          {hasOverride ? (
            <span
              data-testid="band-summary-override-active"
              className="rounded bg-accent px-1.5 py-0.5 text-[10px] text-accent-foreground"
            >
              {t("series.bandSummary.overrideActive")}
            </span>
          ) : null}
        </span>
        <ChevronDown
          className={`h-3 w-3 text-muted-foreground transition-transform ${open ? "rotate-180" : ""}`}
        />
      </button>

      {open ? (
        <div className="space-y-3 border-t border-border px-3 py-2">
          <div
            data-testid="band-summary-generated-at"
            className="text-[10px] text-muted-foreground"
          >
            {t("series.bandSummary.autoGenerated", { date: generatedDate })}
          </div>

          <p
            data-testid="band-summary-full"
            className="whitespace-pre-wrap text-xs text-foreground"
          >
            {hasOverride ? data.override : (data.full_summary ?? data.short_summary ?? "")}
          </p>

          <button
            type="button"
            data-testid="band-summary-regenerate"
            onClick={() => generate.mutate()}
            disabled={generate.isPending}
            className="flex items-center gap-1 text-xs text-primary hover:underline disabled:opacity-50"
          >
            {generate.isPending ? (
              <Loader2 className="h-3 w-3 animate-spin" />
            ) : (
              <RefreshCw className="h-3 w-3" />
            )}
            {t("series.bandSummary.regenerate")}
          </button>

          <BandOverrideEditor
            seriesId={seriesId}
            novelId={novelId}
            initialOverride={data.override}
          />
        </div>
      ) : null}
    </div>
  );
}
